(async () => {
 const fonts = [{family:'Inter',style:'Regular'},{family:'Inter',style:'Medium'},{family:'Inter',style:'Semi Bold'}];
 await Promise.all(fonts.map(f=>figma.loadFontAsync(f)));
 const page=figma.currentPage;
 const color=hex=>({r:parseInt(hex.slice(1,3),16)/255,g:parseInt(hex.slice(3,5),16)/255,b:parseInt(hex.slice(5,7),16)/255});
 const paint=token=>[{type:'SOLID',color:color(WORKSPACE.tokens[token])}];
 const collection=figma.variables.createVariableCollection('Standard Metrics / Prototype tokens');
 const vars={};
 for(const [key,hex] of Object.entries(WORKSPACE.tokens)) {
  const v=figma.variables.createVariable('color/'+key,collection,'COLOR');
  v.scopes=['FRAME_FILL','SHAPE_FILL','TEXT_FILL','STROKE_COLOR'];
  v.setValueForMode(collection.defaultModeId,color(hex));v.setVariableCodeSyntax('WEB','var(--sm-'+key+')');vars[key]=v;
 }
 function boundPaint(token){return [figma.variables.setBoundVariableForPaint(paint(token)[0],'color',vars[token])];}
 function build(e,parent) {
  let n;
  if(e.type==='group'){ n=figma.createFrame();n.fills=[];n.clipsContent=false; }
  else if(e.type==='rect'){n=figma.createRectangle();n.fills=boundPaint(e.fill);n.cornerRadius=e.radius;if(e.border){n.strokes=boundPaint(e.border);n.strokeWeight=1;}}
  else { n=figma.createText();n.fontName=fonts[e.weight>=600?2:e.weight>=500?1:0];n.fontSize=e.size;n.lineHeight={unit:'PIXELS',value:e.lineHeight};n.characters=e.text;n.fills=boundPaint(e.color);n.textAutoResize='HEIGHT'; }
  n.name=e.name;parent.appendChild(n);n.resize(e.width,e.height);n.x=e.x;n.y=e.y;
  if(e.children) e.children.forEach(c=>build(c,n));
  return n;
 }
 const origin=Math.max(0,...page.children.map(n=>n.x+n.width))+160;
 const created=[];
 WORKSPACE.frames.forEach((f,i)=>{const n=figma.createFrame();n.name=f.name;n.resize(f.width,f.height);n.x=origin+(i%2)*1600;n.y=Math.floor(i/2)*1400;n.fills=boundPaint('canvas');n.clipsContent=false;f.children.forEach(e=>build(e,n));created.push(n);});
 figma.currentPage.selection=created;figma.viewport.scrollAndZoomIntoView(created);figma.closePlugin('Imported 4 editable interview frames with native text and shared color tokens.');
})().catch(error=>figma.closePlugin('Import failed: '+error.message));
